package com.crm.customer.service;
import com.crm.customer.entity.*;import com.crm.customer.repository.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.data.domain.*;import jakarta.validation.constraints.*;import java.time.LocalDateTime;import java.util.*;
@Service @Transactional public class ClientCaseService {private final CustomerPersonalService personal;private final CustomerRepository customers;private final ClientCaseRepository cases;private final ClientCaseMessageRepository messages;private final ClientCaseEventRepository events;@jakarta.persistence.PersistenceContext private jakarta.persistence.EntityManager em;
 public ClientCaseService(CustomerPersonalService p,CustomerRepository c,ClientCaseRepository r,ClientCaseMessageRepository m,ClientCaseEventRepository e){personal=p;customers=c;cases=r;messages=m;events=e;}
 public record NewCase(@NotBlank @Size(min=36,max=36) String requestId,@NotBlank @Size(max=200) String subject,@NotBlank @Size(max=4000) String description){}
 public record Message(@NotBlank @Size(min=36,max=36) String requestId,@NotBlank @Size(max=4000) String body){}
 public record State(@NotNull @Pattern(regexp="OPEN|IN_PROGRESS|RESOLVED") String status){}
 public record View(String id,String customerId,String subject,String description,String status,LocalDateTime createdAt){}
 public record Reply(String id,String senderKind,String body,LocalDateTime createdAt){}
 public record Event(String id,String status,LocalDateTime createdAt){}
 private Long scope(boolean admin){ContactAccess.role(admin?new String[]{"ROLE_ADMIN","ROLE_SUPER_ADMIN"}:new String[]{"ROLE_CLIENT"});return admin?null:CustomerPersonalService.id(personal.own(ContactAccess.auth()).customerId());}
 private ClientCase owned(long id,Long customer,boolean lock){var row=(lock?cases.lock(id):cases.findById(id)).orElseThrow(ContactAccess::missing);if(em!=null&&lock)em.refresh(row,jakarta.persistence.LockModeType.PESSIMISTIC_WRITE);if(customer!=null&&!customer.equals(row.getCustomerId()))throw ContactAccess.missing();return row;}
 @Transactional(readOnly=true) public Page<View> list(boolean admin,String status,int page){Long customer=scope(admin);if(status!=null&&!Set.of("OPEN","IN_PROGRESS","RESOLVED").contains(status))throw new IllegalArgumentException("Invalid request status");return cases.search(customer,status,ContactAccess.page(page)).map(r->view(r,admin));}
 @Transactional(readOnly=true) public View detail(boolean admin,long id){return view(owned(id,scope(admin),false),admin);}
 public View create(NewCase input){Long customer=scope(false);ContactAccess.valid(input);uuid(input.requestId());var contact=customers.lockById(customer).orElseThrow(ContactAccess::missing);if(em!=null)em.refresh(contact,jakarta.persistence.LockModeType.PESSIMISTIC_WRITE);var old=cases.findByRequestId(input.requestId());if(old.isPresent()){var row=old.get();if(!row.getCustomerId().equals(customer)||!row.getSubject().equals(input.subject().trim())||!row.getDescription().equals(input.description().trim()))throw ContactAccess.conflict();return view(row,false);}if(contact.isArchived())throw ContactAccess.conflict();var row=new ClientCase();row.setCustomerId(customer);row.setSubject(input.subject().trim());row.setDescription(input.description().trim());row.setRequestId(input.requestId());row=cases.saveAndFlush(row);event(row,ContactAccess.role("ROLE_CLIENT"));return view(row,false);}
 @Transactional(readOnly=true) public Page<Reply> messages(boolean admin,long id,int page){owned(id,scope(admin),false);return messages.findByCaseId(id,ContactAccess.page(page).withSort(Sort.by("id").ascending())).map(this::reply);}
 public Reply send(boolean admin,long id,Message input){Long customer=scope(admin);ContactAccess.valid(input);uuid(input.requestId());var row=owned(id,customer,true);var old=messages.findByRequestId(input.requestId());String kind=admin?"TEAM":"CLIENT";long actor=ContactAccess.role(admin?new String[]{"ROLE_ADMIN","ROLE_SUPER_ADMIN"}:new String[]{"ROLE_CLIENT"});if(old.isPresent()){var message=old.get();if(!Long.valueOf(id).equals(message.getCaseId())||!message.getAuthorId().equals(actor)||!message.getBody().equals(input.body().trim()))throw ContactAccess.conflict();return reply(message);}if(row.getStatus().equals("RESOLVED"))throw ContactAccess.conflict();var message=new ClientCaseMessage();message.setCaseId(id);message.setBody(input.body().trim());message.setRequestId(input.requestId());message.setSenderKind(kind);message.setAuthorId(actor);return reply(messages.saveAndFlush(message));}
 public View state(long id,State input){scope(true);ContactAccess.valid(input);var row=owned(id,null,true);if(!row.getStatus().equals(input.status())){row.setStatus(input.status());event(row,ContactAccess.role("ROLE_ADMIN","ROLE_SUPER_ADMIN"));}return view(row,true);}
 @Transactional(readOnly=true) public Page<Event> history(boolean admin,long id,int page){owned(id,scope(admin),false);return events.findByCaseId(id,ContactAccess.page(page).withSort(Sort.by("id").ascending())).map(e->new Event(e.getId().toString(),e.getStatus(),e.getCreatedAt()));}
 private void event(ClientCase row,long actor){var e=new ClientCaseEvent();e.setCaseId(row.getId());e.setStatus(row.getStatus());e.setAuthorId(actor);events.saveAndFlush(e);}
 private void uuid(String value){try{if(!UUID.fromString(value).toString().equals(value))throw new IllegalArgumentException();}catch(RuntimeException e){throw new IllegalArgumentException("Canonical request UUID required");}}
 private View view(ClientCase r,boolean admin){return new View(r.getId().toString(),admin?r.getCustomerId().toString():null,r.getSubject(),r.getDescription(),r.getStatus(),r.getCreatedAt());}private Reply reply(ClientCaseMessage r){return new Reply(r.getId().toString(),r.getSenderKind(),r.getBody(),r.getCreatedAt());}
}
